-- 11. Quarantine: a leaking bottle at MA5 waiting for Rina's decision, and a damaged tube at
-- KJ5 that Sari wants written off (waiting for Ops HQ). Keyed by source_ref 'seed' 1 and 2.

-- 12. Counts: Ops HQ's cycles (Labore every 2 weeks, Kahf every 4 weeks from 28 Sep), the
-- week's closed count tasks with one difference at MA5 (approved by Rina, reviewed by
-- Andi), and the missing-item bins counted the next morning.
SELECT 'brand', 11, 2, 'week', '2026-09-28', 1, 'andi.pratama@ninjavan.co', '2026-09-26 08:00:00' FROM DUAL
 WHERE NOT EXISTS (SELECT 1 FROM count_cycles WHERE scope = 'brand' AND brand_id = 11);
SELECT 'brand', 10, 4, 'week', '2026-09-28', 1, 'andi.pratama@ninjavan.co', '2026-09-26 08:00:00' FROM DUAL
 WHERE NOT EXISTS (SELECT 1 FROM count_cycles WHERE scope = 'brand' AND brand_id = 10);

-- 13. The ledger. Every unit the seed puts on a shelf or takes off is a stock movement
-- (scan_source 'seed'), and the balances below are what these movements add up to.
SELECT pt.site_id, pl.sku_id, pl.location_id, -pl.qty_picked, 'pick_out', 'pick_line', pl.id, NULL, pt.claimed_by, 'seed', 0,
       DATE_ADD(pt.started_at, INTERVAL pl.sequence_no * 30 SECOND), NULL, 'brand'
  FROM pick_lines pl JOIN pick_tasks pt ON pt.id = pl.pick_task_id
  JOIN orders o ON o.id = pt.order_id
 WHERE o.external_ref LIKE 'SEED-%' AND pl.qty_picked > 0;
SELECT f.site_id, f.sku_id, f.location_id, f.qty_found - f.qty_before, 'adjustment', 'pick_line', f.ref_id, 'short_pick', f.raised_by, 'seed', 0, f.created_at, NULL, 'brand'
  FROM bin_count_flags f WHERE f.site_id IN (2, 4) AND f.raised_by IN ('dimas.pratama@ninjavan.co', 'ayu.lestari@ninjavan.co', 'eko.prasetyo@ninjavan.co', 'rina.saputri@ninjavan.co', 'andi.pratama@ninjavan.co', 'bayu.hidayat@ninjavan.co', 'sari.wulandari@ninjavan.co', 'fajar.ramadhan@ninjavan.co', 'rizky.maulana@ninjavan.co')
   AND f.reason = 'short_pick' AND f.qty_before > f.qty_found;
SELECT p.site_id, p.sku_id, p.location_id, p.qty, 'receipt_in', 'receipt', p.receipt_id, CONCAT('putaway:', p.load_id), p.actor_email, 'seed', 0, p.created_at, p.day_color_key, 'brand'
  FROM inbound_putaways p JOIN inbound_receipts ir ON ir.id = p.receipt_id
  JOIN replenishments r ON r.id = ir.replenishment_id
 WHERE r.reference = 'RPL-MA5-2609-001' AND r.created_by = 'andi.pratama@ninjavan.co';
SELECT q.site_id, q.sku_id, q.location_id, -q.qty, 'adjustment', 'quarantine_item', q.id, 'quarantine', q.reported_by, 'seed', 0, q.reported_at, NULL, 'brand'
  FROM quarantine_items q WHERE q.source_ref_type = 'seed' AND q.in_ledger = 1;
SELECT t.site_id, t.sku_id, t.location_id, t.variance, 'adjustment', 'count_task', t.id, 'count', t.approved_by, 'seed', 0, t.approved_at, NULL, 'brand'
  FROM count_tasks t WHERE t.site_id IN (2, 4) AND t.approved_by IN ('dimas.pratama@ninjavan.co', 'ayu.lestari@ninjavan.co', 'eko.prasetyo@ninjavan.co', 'rina.saputri@ninjavan.co', 'andi.pratama@ninjavan.co', 'bayu.hidayat@ninjavan.co', 'sari.wulandari@ninjavan.co', 'fajar.ramadhan@ninjavan.co', 'rizky.maulana@ninjavan.co') AND t.variance <> 0;
UPDATE inbound_putaways p JOIN stock_movements m ON m.scan_source = 'seed' AND m.ref_type = 'receipt'
   AND m.ref_id = p.receipt_id AND m.reason_code = CONCAT('putaway:', p.load_id)
   SET p.movement_id = m.id WHERE p.site_id = 4;
UPDATE count_tasks t JOIN stock_movements m ON m.scan_source = 'seed' AND m.ref_type = 'count_task' AND m.ref_id = t.id
   SET t.movement_id = m.id WHERE t.site_id IN (2, 4);

