SELECT c.id, c.site_id, CASE c.name WHEN 'Gulungan label bin' THEN -1 WHEN 'Kantong kertas Berkah PBG15' THEN -1 END, 'order', 'order', o.id, 'ayu.lestari@ninjavan.co', '2026-10-04 13:29:05'
  FROM consumables c JOIN orders o ON o.external_ref = 'SEED-MA5-1004-2020'
 WHERE c.site_id = 4 AND c.name IN ('Gulungan label bin', 'Kantong kertas Berkah PBG15');
SELECT c.id, c.site_id, CASE c.name WHEN 'Gulungan label bin' THEN -1 WHEN 'Kantong kertas Berkah PBG15' THEN -1 END, 'order', 'order', o.id, 'rizky.maulana@ninjavan.co', '2026-10-04 13:38:25'
  FROM consumables c JOIN orders o ON o.external_ref = 'SEED-KJ5-1004-2030'
 WHERE c.site_id = 2 AND c.name IN ('Gulungan label bin', 'Kantong kertas Berkah PBG15');
SELECT c.id, c.site_id, -1, 'delivery', 'replenishment', r.id, 'eko.prasetyo@ninjavan.co', '2026-09-30 04:07:22'
  FROM consumables c JOIN replenishments r ON r.reference = 'RPL-MA5-2609-001' AND r.created_by = 'andi.pratama@ninjavan.co'
 WHERE c.site_id = 4 AND c.name IN ('Sekat warna', 'Stiker warna hari');
SELECT c.id, 4, 'closed', 100, 'Kantong untuk 2 minggu', 'rina.saputri@ninjavan.co', '2026-09-29 09:00:00', 'PR-NV-2609-0143', 100, 'andi.pratama@ninjavan.co', '2026-09-30 02:15:00', '2026-10-02 08:00:00' FROM consumables c
 WHERE c.site_id = 4 AND c.name = 'Kantong kertas Berkah PBG15' AND NOT EXISTS (SELECT 1 FROM consumable_requests q WHERE q.consumable_id = c.id AND q.raised_by = 'rina.saputri@ninjavan.co' AND q.raised_at = '2026-09-29 09:00:00');
SELECT c.id, 4, q.id, 2, 50, 100, 'approved', 'rina.saputri@ninjavan.co', '2026-10-02 06:30:00', 'andi.pratama@ninjavan.co', '2026-10-02 08:00:00'
  FROM consumables c JOIN consumable_requests q ON q.consumable_id = c.id AND q.raised_by = 'rina.saputri@ninjavan.co' AND q.raised_at = '2026-09-29 09:00:00'
 WHERE c.site_id = 4 AND c.name = 'Kantong kertas Berkah PBG15' AND NOT EXISTS (SELECT 1 FROM consumable_receipts x WHERE x.request_id = q.id);
SELECT x.consumable_id, x.site_id, x.qty_total, 'receipt', 'consumable_receipt', x.id, 'andi.pratama@ninjavan.co', x.decided_at
  FROM consumable_receipts x JOIN consumables c ON c.id = x.consumable_id
 WHERE c.site_id = 4 AND c.name = 'Kantong kertas Berkah PBG15' AND x.entered_by = 'rina.saputri@ninjavan.co' AND x.entered_at = '2026-10-02 06:30:00';
UPDATE consumables c SET c.stock_qty = COALESCE((SELECT SUM(m.qty_delta) FROM consumable_movements m WHERE m.consumable_id = c.id), 0)
 WHERE c.site_id IN (2, 4) AND NOT EXISTS (SELECT 1 FROM audit_log WHERE entity = 'dev_seed' AND action = 'seed_layout_v3');

-- 15. The SPV's note for the morning after the week, and the kick-off steps nobody but a
-- person can tick (devices, training, watching the first orders).

-- Done: the marker that keeps the one-time reset from running again.
SELECT 'seed@ninjavan.co', 'dev_seed', 3, 'seed_layout_v3', '{"note": "dev seed for deploy 3: racks, stock and history"}' FROM DUAL
 WHERE NOT EXISTS (SELECT 1 FROM audit_log WHERE entity = 'dev_seed' AND action = 'seed_layout_v3');
